CategoryTheory.Adjunction.homEquiv_naturality_right.{v₁, v₂, u₁, u₂} {C : Type u₁} [Category.{v₁, u₁} C] {D : Type u₂}
  [Category.{v₂, u₂} D] {F : C ⥤ D} {G : D ⥤ C} (adj : F ⊣ G) {X : C} {Y Y' : D} (f : F.obj X ⟶ Y) (g : Y ⟶ Y') :
  (adj.homEquiv X Y') (f ≫ g) = (adj.homEquiv X Y) f ≫ G.map g

CategoryTheory.Adjunction.left_triangle.code:
