CategoryTheory.Adjunction.left_triangle_components.{v₁, v₂, u₁, u₂} {C : Type u₁} [Category.{v₁, u₁} C] {D : Type u₂}
  [Category.{v₂, u₂} D] {F : C ⥤ D} {G : D ⥤ C} (adj : F ⊣ G) (X : C) :
