  [Category.{u_2, u_1} M] [MonoidalCategory M] (F : MonoidalFunctor M (C ⥤ C)) (m₁ m₂ m₃ : M) (X : C) {Z : C}
  (h : (F.obj (m₁ ⊗ m₂ ⊗ m₃)).obj X ⟶ Z) :
  (F.obj m₃).map ((F.μ m₁ m₂).app X) ≫ (F.μ (m₁ ⊗ m₂) m₃).app X ≫ (F.map (α_ m₁ m₂ m₃).hom).app X ≫ h =
    (F.μ m₂ m₃).app ((F.obj m₁).obj X) ≫ (F.μ m₁ (m₂ ⊗ m₃)).app X ≫ h

