  [Category.{v₁, u₁} C] {D : Type u₂} [Category.{v₁, u₂} D] {F : C ⥤ D} {G : (Cᵒᵖ ⥤ Type v₁) ⥤ Dᵒᵖ ⥤ Type v₁}
