  [Category.{u_4, u_1} C] [Category.{u_6, u_2} D] (L : C ⥤ D) (W : MorphismProperty C) {E : Type u_3}
  [Category.{u_5, u_3} E] [L.IsLocalization W] (F₁ F₂ : C ⥤ E) (F₁' F₂' : D ⥤ E) [Lifting L W F₁ F₁']
  [Lifting L W F₂ F₂'] (τ : F₁ ⟶ F₂) (X : C) :
  (liftNatTrans L W F₁ F₂ F₁' F₂' τ).app (L.obj X) =
    (Lifting.iso L W F₁ F₁').hom.app X ≫ τ.app X ≫ (Lifting.iso L W F₂ F₂').inv.app X

