CategoryTheory.Functor.FullyFaithful.hasShift.map_add_hom_app.{v, u, u_1, u_2, u_3} {C : Type u} {A : Type u_1}
  [Category.{v, u} C] {D : Type u_2} [Category.{u_3, u_2} D] [AddMonoid A] [HasShift D A] {F : C ⥤ D}
  (hF : F.FullyFaithful) (s : A → C ⥤ C) (i : (i : A) → s i ⋙ F ≅ F ⋙ shiftFunctor D i) (a b : A) (X : C) :
  F.map ((add hF s i a b).hom.app X) =
    (i (a + b)).hom.app X ≫
      (shiftFunctorAdd D a b).hom.app (F.obj X) ≫ (shiftFunctor D b).map ((i a).inv.app X) ≫ (i b).inv.app ((s a).obj X)

CategoryTheory.Functor.FullyFaithful.hasShift.map_add_inv_app.{v, u, u_1, u_2, u_3} {C : Type u} {A : Type u_1}
  [Category.{v, u} C] {D : Type u_2} [Category.{u_3, u_2} D] [AddMonoid A] [HasShift D A] {F : C ⥤ D}
  (hF : F.FullyFaithful) (s : A → C ⥤ C) (i : (i : A) → s i ⋙ F ≅ F ⋙ shiftFunctor D i) (a b : A) (X : C) :
  F.map ((add hF s i a b).inv.app X) =
    (i b).hom.app ((s a).obj X) ≫
      (shiftFunctor D b).map ((i a).hom.app X) ≫ (shiftFunctorAdd D a b).inv.app (F.obj X) ≫ (i (a + b)).inv.app X

